'use strict';
const {base,P1,P1P2,candidate,printer,pins,sha,fs,path,root,range,once,template,edgeHoist,topologyCache,assert,writeReceipt}=require('./test-support.cjs');
const checks=[],check=(name,fn)=>{fn();checks.push(name);},prior=JSON.parse(fs.readFileSync(path.join(root,'prior-clearances.json'),'utf8'));
const fn=(s,n)=>{const r=range(s,n);return s.slice(r.start,r.end);};
check('exact published r241 worker/printer and cleared P3 template',()=>{assert.equal(sha(base),pins.worker);assert.equal(sha(printer),pins.printer);assert.equal(sha(template),prior.P3.templateSHA256);});
check('P2 raw transformation reconstructs cleared exact hash',()=>assert.equal(sha(edgeHoist(base)),prior.P2.rawP2SHA256));
check('P3 authenticated transformation reconstructs cleared raw P2+P3 exact hash',()=>assert.equal(sha(topologyCache(edgeHoist(base))),prior.P3.rawP2P3SHA256));
check('raw P1 retains original component, groups and reservation implementations',()=>{for(const n of ['insetComponent','insetGroups','reserveInset','describeContours'])assert.equal(fn(base,n),fn(P1,n));});
check('P1 owner call changes only oversized-description branch after drain',()=>{const call='api.insetDescription(section.description,p)';assert.equal(P1.split(call).length,2);assert(P1.includes("if(size>maxJobBytes){await drain();status.mark('building-paths',layer);entry.job.values=["+call+']'));assert(P1.includes("if(!slots){status.mark('building-paths',layer);entry.job.values=[api.insetGroups(section.groups,p)]"));});
check('all bytes outside exact approved sites remain published r241',()=>{
 function strip(s){s=s.replace(template+'\n  ','').replace('const api={baselineTopologyCacheDiagnostics,','const api={').replace('insetGroups,insetDescription,layerY','insetGroups,layerY').replace('api.insetDescription(section.description,p)','api.insetGroups(section.groups,p)');
  for(const n of ['insetPreparedComponent','insetDescription'])if(s.includes('function '+n+'(')){const r=range(s,n);s=s.slice(0,r.start)+s.slice(r.end);}
  s=s.replace(/\n  \n  \n  function insetContours/,'\n  function insetContours');
  for(const n of ['trajectoryQualityFailures','oneSidedPostRdpCleanup','proposeTwoPercentInset','simplifyInset']){const r=range(s,n);s=s.slice(0,r.start)+'FUNCTION:'+n+s.slice(r.end);}return s;
 }
 assert.equal(strip(candidate),strip(base));
});
check('geometry generators, shared pool and printer stay byte exact',()=>{for(const [a,z]of [['const frameAdaptiveSectionCache=new WeakMap();','function frameR180FinalizeLayerJob('],['function frameSpiralSourceRequiresAcuteBreak(',null]]){const end=(s)=>z?s.indexOf(z,s.indexOf(a)):s.length;assert.equal(candidate.slice(candidate.indexOf(a),end(candidate)),base.slice(base.indexOf(a),end(base)));}assert.equal(fn(candidate,'frameSectionLayer'),fn(base,'frameSectionLayer'));assert.equal(fn(candidate,'frameR180FinalizeLayerJob'),fn(base,'frameR180FinalizeLayerJob'));});
check('production packet/cache/work limits and admission signatures unchanged',()=>{for(const q of ['maxJobBytes=4194304,maxRetained=268435456,maxOutput=67108864','minimumBytes>67108864','preparedBytes>8388608','insetCacheValueLimit=134217728','insetCache.size>128||insetCacheBytes>8000000'])assert(candidate.includes(q));assert.equal(fn(candidate,'frameLayerPacketBytes'),fn(base,'frameLayerPacketBytes'));assert.equal(fn(candidate,'framePreparedGeometry'),fn(base,'framePreparedGeometry'));});
check('no QA, nested profiling, counter transport, timer or pool addition',()=>{for(const q of ['frameSlicerPerformanceActive','framePerformanceMeasure','frameSimplifyMeasure','frameCacheObserver','qaPlan','qaCommit','FrameHeavyQA','FrameP3Routing','baselineTopologyCachePack','helperCache','performanceDiagnostics'])assert(!candidate.includes(q),q);for(const q of ['setTimeout(','setInterval(','new Worker(','new MessageChannel('])assert.equal(candidate.split(q).length,base.split(q).length,q);assert(!template.includes('postMessage'));});
check('module version and original protocol API preserved',()=>{assert(candidate.includes("version:'counted-original-insets-1'"));assert.equal(candidate.match(/version:'counted-original-insets-1'/g).length,1);assert.equal(sha(printer),pins.printer);});
check('P2 resets cached current edges after every removal',()=>{assert(P1P2.includes('while(remainingBudget-->0){let selected=null,currentEdges=null;'));assert(P1P2.includes('const edges=currentEdges||(currentEdges=pathEdges(current)),after={a:start,b:end};'));});
check('current r242 shell and actual loaded worker agree with the cleared candidate',()=>{const repo=require('./build.cjs').repo,index=fs.readFileSync(path.join(repo,'index.html'),'utf8'),m=JSON.parse(index.match(/<script id="frame-assets" type="application\/json">([\s\S]*?)<\/script>/)[1]),w=m.assets['slicer-worker'];assert.equal(m.version,'r242-slicer-cache');assert.equal(Object.keys(m.assets).length,57);assert.equal(w.sha256,sha(candidate));assert.equal(w.bytes,Buffer.byteLength(candidate));assert.equal(sha(fs.readFileSync(path.join(repo,w.path))),sha(candidate));});
writeReceipt('source-receipt.json','FRAME_P123_SOURCE_BOUNDARIES_COMPLETED',checks,{independentShippingClearance:false});
